CREATE OR REPLACE FUNCTION buildpulse_enforce_verified_story_provenance() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.verification_state='verified' AND (NEW.verified_at IS NULL OR NEW.verified_by IS NULL OR coalesce(trim(NEW.canonical_source_url),'')='') THEN RAISE EXCEPTION 'verified BuildPulse story requires reviewer, timestamp and canonical source'; END IF; RETURN NEW; END $$; DROP TRIGGER IF EXISTS trg_buildpulse_verified_story_provenance ON buildpulse_stories; CREATE TRIGGER trg_buildpulse_verified_story_provenance BEFORE INSERT OR UPDATE ON buildpulse_stories FOR EACH ROW EXECUTE FUNCTION buildpulse_enforce_verified_story_provenance();